import sys

def main():
    input = sys.stdin.buffer.readline
    first = input().split()
    if not first:
        return

    N = int(first[0])
    K = int(first[1])

    if K == 1:
        print("Yes")
        return

    M = N * K
    adj = [[] for _ in range(M + 1)]

    for _ in range(M - 1):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (M + 1)
    parent[1] = -1
    order = []
    stack = [1]

    while stack:
        v = stack.pop()
        order.append(v)
        for to in adj[v]:
            if to == parent[v]:
                continue
            if parent[to] != 0:
                continue
            parent[to] = v
            stack.append(to)

    # state: 0 = impossible, 1 = closed (fully partitioned), 2 = open
    state = [0] * (M + 1)
    rem = [0] * (M + 1)

    for v in reversed(order):
        open_cnt = 0
        s = 1
        ok = True

        for to in adj[v]:
            if parent[to] == v:
                st = state[to]
                if st == 0:
                    ok = False
                elif st == 2:
                    open_cnt += 1
                    s += rem[to]

        rem[v] = s % K

        if not ok:
            state[v] = 0
        elif open_cnt == 0:
            state[v] = 2
        elif open_cnt == 1:
            state[v] = 1 if rem[v] == 0 else 2
        elif open_cnt == 2:
            state[v] = 1 if rem[v] == 0 else 0
        else:
            state[v] = 0

    print("Yes" if state[1] == 1 else "No")

if __name__ == "__main__":
    main()

from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_right = [[] for _ in range(n + 1)]

        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            by_right[b].append((a, i))

        gain = [0] * m

        max1 = 0
        cnt1 = 0
        id1 = -1
        max2 = 0
        base = 0

        for r in range(1, n + 1):
            for u, idx in by_right[r]:
                if u > max1:
                    max2 = max1
                    max1 = u
                    cnt1 = 1
                    id1 = idx
                elif u == max1:
                    cnt1 += 1
                    id1 = -1
                elif u > max2:
                    max2 = u

            base += r - max1

            if cnt1 == 1:
                gain[id1] += max1 - max2

        if m == 0:
            return n * (n + 1) // 2

        return base + max(gain)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def required_counts(length: int, start_parity: int):
            if start_parity == 1:
                return (length + 1) // 2, length // 2
            return length // 2, (length + 1) // 2

        used = [False] * (n + 1)
        rem_odd = (n + 1) // 2
        rem_even = n // 2
        ans = []
        prev_parity = None

        for pos in range(n):
            chosen = None

            for x in range(1, n + 1):
                if used[x]:
                    continue

                parity = x & 1
                if prev_parity is not None and parity == prev_parity:
                    continue

                if parity == 1:
                    if rem_odd == 0:
                        continue
                    next_odd = rem_odd - 1
                    next_even = rem_even
                else:
                    if rem_even == 0:
                        continue
                    next_odd = rem_odd
                    next_even = rem_even - 1

                remaining_length = n - pos - 1
                need_odd, need_even = required_counts(remaining_length, 1 - parity)

                if next_odd != need_odd or next_even != need_even:
                    continue

                count = fact[next_odd] * fact[next_even]

                if count >= k:
                    chosen = x
                    break

                k -= count

            if chosen is None:
                return []

            used[chosen] = True
            ans.append(chosen)

            if chosen & 1:
                rem_odd -= 1
            else:
                rem_even -= 1

            prev_parity = chosen & 1

        return ans

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        if not grid or not grid[0]:
            return 0

        n = len(grid)
        m = len(grid[0])
        N = n * m
        vals = [x for row in grid for x in row]

        if 1 not in vals:
            return 0

        # Directions:
        # 0: down-right, 1: down-left, 2: up-left, 3: up-right
        # Clockwise turn: d -> (d + 1) % 4

        def compute_straight(d):
            odd = [0] * N    # max valid straight segment length ending here, odd length
            even = [0] * N   # max valid straight segment length ending here, even length
            best = 0

            v = vals
            mm = m
            nn = n
            last_row = nn - 1
            last_col = mm - 1

            if d == 0:  # down-right
                for i in range(nn):
                    base = i * mm
                    for j in range(mm):
                        idx = base + j
                        val = v[idx]

                        o = 1 if val == 1 else 0
                        e = 0

                        if i and j:
                            p = idx - mm - 1
                            if val == 2:
                                po = odd[p]
                                if po:
                                    e = po + 1
                            elif val == 0:
                                pe = even[p]
                                if pe:
                                    o = pe + 1

                        odd[idx] = o
                        even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            elif d == 1:  # down-left
                for i in range(nn):
                    base = i * mm
                    for j in range(mm):
                        idx = base + j
                        val = v[idx]

                        o = 1 if val == 1 else 0
                        e = 0

                        if i and j < last_col:
                            p = idx - mm + 1
                            if val == 2:
                                po = odd[p]
                                if po:
                                    e = po + 1
                            elif val == 0:
                                pe = even[p]
                                if pe:
                                    o = pe + 1

                        odd[idx] = o
                        even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            elif d == 2:  # up-left
                for i in range(nn - 1, -1, -1):
                    base = i * mm
                    for j in range(mm - 1, -1, -1):
                        idx = base + j
                        val = v[idx]

                        o = 1 if val == 1 else 0
                        e = 0

                        if i < last_row and j < last_col:
                            p = idx + mm + 1
                            if val == 2:
                                po = odd[p]
                                if po:
                                    e = po + 1
                            elif val == 0:
                                pe = even[p]
                                if pe:
                                    o = pe + 1

                        odd[idx] = o
                        even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            else:  # d == 3, up-right
                for i in range(nn - 1, -1, -1):
                    base = i * mm
                    for j in range(mm):
                        idx = base + j
                        val = v[idx]

                        o = 1 if val == 1 else 0
                        e = 0

                        if i < last_row and j:
                            p = idx + mm - 1
                            if val == 2:
                                po = odd[p]
                                if po:
                                    e = po + 1
                            elif val == 0:
                                pe = even[p]
                                if pe:
                                    o = pe + 1

                        odd[idx] = o
                        even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            return best, odd, even

        def compute_turned(d, src_odd, src_even):
            t_odd = [0] * N   # max valid turned segment length ending here, odd length
            t_even = [0] * N  # max valid turned segment length ending here, even length
            best = 0

            v = vals
            mm = m
            nn = n
            last_row = nn - 1
            last_col = mm - 1

            if d == 0:  # down-right
                for i in range(nn):
                    base = i * mm
                    for j in range(mm):
                        idx = base + j
                        val = v[idx]

                        o = src_odd[idx]
                        e = src_even[idx]

                        if i and j:
                            p = idx - mm - 1
                            if val == 2:
                                po = t_odd[p]
                                if po:
                                    cand = po + 1
                                    if cand > e:
                                        e = cand
                            elif val == 0:
                                pe = t_even[p]
                                if pe:
                                    cand = pe + 1
                                    if cand > o:
                                        o = cand

                        t_odd[idx] = o
                        t_even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            elif d == 1:  # down-left
                for i in range(nn):
                    base = i * mm
                    for j in range(mm):
                        idx = base + j
                        val = v[idx]

                        o = src_odd[idx]
                        e = src_even[idx]

                        if i and j < last_col:
                            p = idx - mm + 1
                            if val == 2:
                                po = t_odd[p]
                                if po:
                                    cand = po + 1
                                    if cand > e:
                                        e = cand
                            elif val == 0:
                                pe = t_even[p]
                                if pe:
                                    cand = pe + 1
                                    if cand > o:
                                        o = cand

                        t_odd[idx] = o
                        t_even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            elif d == 2:  # up-left
                for i in range(nn - 1, -1, -1):
                    base = i * mm
                    for j in range(mm - 1, -1, -1):
                        idx = base + j
                        val = v[idx]

                        o = src_odd[idx]
                        e = src_even[idx]

                        if i < last_row and j < last_col:
                            p = idx + mm + 1
                            if val == 2:
                                po = t_odd[p]
                                if po:
                                    cand = po + 1
                                    if cand > e:
                                        e = cand
                            elif val == 0:
                                pe = t_even[p]
                                if pe:
                                    cand = pe + 1
                                    if cand > o:
                                        o = cand

                        t_odd[idx] = o
                        t_even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            else:  # d == 3, up-right
                for i in range(nn - 1, -1, -1):
                    base = i * mm
                    for j in range(mm):
                        idx = base + j
                        val = v[idx]

                        o = src_odd[idx]
                        e = src_even[idx]

                        if i < last_row and j:
                            p = idx + mm - 1
                            if val == 2:
                                po = t_odd[p]
                                if po:
                                    cand = po + 1
                                    if cand > e:
                                        e = cand
                            elif val == 0:
                                pe = t_even[p]
                                if pe:
                                    cand = pe + 1
                                    if cand > o:
                                        o = cand

                        t_odd[idx] = o
                        t_even[idx] = e

                        if o > best:
                            best = o
                        if e > best:
                            best = e

            return best

        ans = 1

        for d in range(4):
            best_straight, odd, even = compute_straight(d)
            if best_straight > ans:
                ans = best_straight

            best_turned = compute_turned((d + 1) % 4, odd, even)
            if best_turned > ans:
                ans = best_turned

            odd = even = None

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)

        first = p.find('*')
        second = p.find('*', first + 1)
        if first == -1 or second == -1:
            return -1

        A = p[:first]
        B = p[first + 1:second]
        C = p[second + 1:]

        if not A and not B and not C:
            return 0

        def occurrences(pat: str, text: str):
            m = len(pat)
            if m == 0 or m > len(text):
                return []

            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j > 0 and pat[i] != pat[j]:
                    j = pi[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                pi[i] = j

            res = []
            j = 0
            for i, ch in enumerate(text):
                while j > 0 and ch != pat[j]:
                    j = pi[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = pi[j - 1]
            return res

        occA = occurrences(A, s) if A else []
        occB = occurrences(B, s) if B else []
        occC = occurrences(C, s) if C else []

        if (A and not occA) or (B and not occB) or (C and not occC):
            return -1

        lenA, lenB, lenC = len(A), len(B), len(C)

        prevA = None
        if A:
            prevA = [-1] * (n + 1)
            for st in occA:
                prevA[st] = st
            for i in range(1, n + 1):
                if prevA[i] == -1:
                    prevA[i] = prevA[i - 1]

        nextC = None
        if C:
            nextC = [-1] * (n + 1)
            for st in occC:
                nextC[st] = st
            for i in range(n - 1, -1, -1):
                if nextC[i] == -1:
                    nextC[i] = nextC[i + 1]

        ans = n + 1

        if B:
            for b in occB:
                if A:
                    pos = b - lenA
                    if pos < 0:
                        continue
                    a = prevA[pos]
                    if a == -1:
                        continue
                else:
                    a = b

                if C:
                    pos = b + lenB
                    if pos > n:
                        continue
                    c = nextC[pos]
                    if c == -1:
                        continue
                else:
                    c = b + lenB

                length = c + lenC - a
                if length < ans:
                    ans = length
        else:
            for b in range(n + 1):
                if A:
                    pos = b - lenA
                    if pos < 0:
                        continue
                    a = prevA[pos]
                    if a == -1:
                        continue
                else:
                    a = b

                if C:
                    c = nextC[b]
                    if c == -1:
                        continue
                else:
                    c = b

                length = c + lenC - a
                if length < ans:
                    ans = length

        return -1 if ans == n + 1 else ans

import sys
from math import gcd, isqrt
from array import array


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    K = data[1]
    write = sys.stdout.write

    def output_const(s, n):
        line = s + '\n'
        chunk = 100000
        if n <= chunk:
            write(line * n)
            return
        block = line * chunk
        full = n // chunk
        for _ in range(full):
            write(block)
        rem = n % chunk
        if rem:
            write(line * rem)

    if K == 1:
        out = []
        append = out.append
        for i in range(2, N + 2):
            append(str(data[i]))
            if len(out) >= 100000:
                write('\n'.join(out) + '\n')
                out.clear()
        if out:
            write('\n'.join(out))
        return

    if K == N:
        g = data[2]
        for i in range(3, N + 2):
            g = gcd(g, data[i])
        output_const(str(g), N)
        return

    MAXV = 1000000
    freq = [0] * (MAXV + 1)
    M = 0
    distinct = 0

    for i in range(2, N + 2):
        x = data[i]
        if freq[x] == 0:
            distinct += 1
        freq[x] += 1
        if x > M:
            M = x

    if M == 1 or distinct == 1:
        output_const(str(data[2]), N)
        return

    A = array('I', data[2:])
    del data

    valid = bytearray(M + 1)
    valid[1] = 1

    f = freq
    k = K
    M1 = M + 1
    half = M // 2

    has_valid = False
    has_valid_small = False

    for d in range(2, half + 1):
        dd = d + d
        s = f[d] + f[dd]
        if s < k:
            for m in range(dd + d, M1, d):
                s += f[m]
                if s >= k:
                    break
        if s >= k:
            valid[d] = 1
            has_valid = True
            has_valid_small = True

    for d in range(half + 1, M1):
        if f[d] >= k:
            valid[d] = 1
            has_valid = True

    del freq, f

    if not has_valid:
        output_const('1', N)
        return

    if not has_valid_small:
        out = []
        append = out.append
        v = valid
        for x in A:
            append(str(x if v[x] else 1))
            if len(out) >= 100000:
                write('\n'.join(out) + '\n')
                out.clear()
        if out:
            write('\n'.join(out))
        return

    P = half
    is_prime = bytearray(b'\x01') * (P + 1)
    is_prime[0] = 0
    if P >= 1:
        is_prime[1] = 0

    r = isqrt(P)
    for i in range(2, r + 1):
        if is_prime[i]:
            start = i * i
            is_prime[start:P + 1:i] = b'\x00' * (((P - start) // i) + 1)

    primes = [i for i in range(2, P + 1) if is_prime[i]]
    del is_prime

    dp = [1] * (M + 1)
    v = valid
    pr = primes

    for x in range(2, half + 1):
        if v[x]:
            val = x
            dp[x] = val
        else:
            val = dp[x]

        if val > 1:
            limit = M // x
            for p in pr:
                if p > limit:
                    break
                z = x * p
                if val > dp[z]:
                    dp[z] = val

    for x in range(half + 1, M1):
        if v[x]:
            dp[x] = x

    out = []
    append = out.append
    dpl = dp
    for x in A:
        append(str(dpl[x]))
        if len(out) >= 100000:
            write('\n'.join(out) + '\n')
            out.clear()
    if out:
        write('\n'.join(out))


if __name__ == '__main__':
    main()

