import sys
from math import gcd, isqrt

MOD = 998244353


def step_min(dp, c, pw, qi, M, mod=MOD):
    # dp[h]: total weight for the processed prefix, where the current exponent
    # is h above the minimum exponent seen so far.
    # M is the maximum possible h in dp (dp has length M+1).
    if c == 0:
        d = dp
        for h in range(1, M + 1):
            v = d[h]
            if v:
                d[h] = (v * pw[h]) % mod
        return d, M

    new_max = M + c
    ndp = [0] * (new_max + 1)
    d = dp

    # Transitions ending at h = 0.
    # From h = c: no new minimum, factor 1.
    zero = d[c] if c <= M else 0

    # From h < c: a new minimum is created.
    # If i positions have already been processed, the factor is q^(i*(c-h)).
    # qi = q^i.
    limit = c - 1
    if limit > M:
        limit = M

    factor = 1
    for _ in range(c - limit):
        factor = (factor * qi) % mod

    for h in range(limit, -1, -1):
        v = d[h]
        if v:
            zero += v * factor
        factor = (factor * qi) % mod

    ndp[0] = zero % mod

    # Transitions ending at h > 0:
    # ndp[h] = q^h * (dp[h-c] + dp[h+c]) when the sources are valid.
    mc = M - c
    tmp = mc + 1

    # Only source h+c (down step from a higher state).
    end1 = c
    if tmp < end1:
        end1 = tmp
    for h in range(1, end1):
        v = d[h + c]
        if v:
            ndp[h] = (v * pw[h]) % mod

    # Both sources are valid.
    start2 = c
    end2 = mc + 1
    if start2 < end2:
        for h in range(start2, end2):
            v = d[h - c] + d[h + c]
            if v >= mod:
                v -= mod
            if v:
                ndp[h] = (v * pw[h]) % mod

    # Only source h-c (up step from a lower state).
    start3 = c
    if tmp > start3:
        start3 = tmp
    for h in range(start3, new_max + 1):
        v = d[h - c]
        if v:
            ndp[h] = (v * pw[h]) % mod

    return ndp, new_max


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N - 1]
    if not A:
        print(1)
        return

    maxA = max(A)
    spf = list(range(maxA + 1))
    if maxA >= 1:
        spf[1] = 1
    for i in range(2, isqrt(maxA) + 1):
        if spf[i] == i:
            for j in range(i * i, maxA + 1, i):
                if spf[j] == j:
                    spf[j] = i

    exps = {}
    for i, val in enumerate(A):
        x = val
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            lst = exps.get(p)
            if lst is None:
                lst = [0] * (N - 1)
                exps[p] = lst
            lst[i] = e

    ans = 1

    for p, lst in exps.items():
        s = 0
        g = 0
        for a in lst:
            if a:
                s += a
                if g == 0:
                    g = a
                else:
                    g = gcd(g, a)

        if g == 0:
            continue

        H = s // g
        q = pow(p, g, MOD)

        powq = [1] * (H + 1)
        for i in range(1, H + 1):
            powq[i] = (powq[i - 1] * q) % MOD

        dp = [1]
        M = 0
        qi = q  # q^i, where i is the current position index (1-based)

        for a in lst:
            c = a // g
            if c:
                dp, M = step_min(dp, c, powq, qi, M)
            elif M:
                dp, M = step_min(dp, 0, powq, qi, M)
            qi = (qi * q) % MOD

        F = sum(dp) % MOD
        ans = (ans * F) % MOD

    print(ans)


