import sys
from array import array
from math import gcd
from bisect import bisect_right


def count_direct_list(vals, R):
    n = len(vals)
    if n < 3:
        return 0

    present = bytearray(R + 1)
    for v in vals:
        present[v] = 1

    evens = [v for v in vals if not (v & 1)]
    odds = [v for v in vals if v & 1]

    ans = 0
    pres = present
    for group in (evens, odds):
        m = len(group)
        for i in range(m - 1):
            a = group[i]
            for j in range(i + 1, m):
                ans += pres[(a + group[j]) >> 1]
    return ans


def count_direct(S, minS, g, R):
    if g == 1:
        vals = [x - minS for x in S]
    else:
        vals = [(x - minS) // g for x in S]
    return count_direct_list(vals, R)


def count_complement(S, minS, g, R):
    present = bytearray(R + 1)
    if g == 1:
        for x in S:
            present[x - minS] = 1
    else:
        for x in S:
            present[(x - minS) // g] = 1

    missing = []
    sum1 = 0
    e = 0
    for i in range(R + 1):
        if not present[i]:
            missing.append(i)
            sum1 += min(i, R - i) + (R - i) // 2 + i // 2
            if not (i & 1):
                e += 1

    K = len(missing)
    o = K - e
    total = (R // 2) * ((R + 1) // 2)

    sum2 = e * (e - 1) // 2 + o * (o - 1) // 2
    for i, u in enumerate(missing):
        sum2 += bisect_right(missing, 2 * u, i + 1, K) - (i + 1)
        sum2 += bisect_right(missing, (R + u) // 2, i + 1, K) - (i + 1)

    missing_ap = count_direct_list(missing, R)
    return total - sum1 + sum2 - missing_ap


def count_bigint(S, minS, g, R):
    ba_len = (20 * R) // 8 + 1
    ba = bytearray(ba_len)

    if g == 1:
        for x in S:
            y = x - minS
            idx = (y * 5) >> 1
            if y & 1:
                ba[idx] = 16
            else:
                ba[idx] = 1
    else:
        for x in S:
            y = (x - minS) // g
            idx = (y * 5) >> 1
            if y & 1:
                ba[idx] = 16
            else:
                ba[idx] = 1

    p = int.from_bytes(ba, "little")
    del ba

    prod = p * p
    del p

    pb = prod.to_bytes(5 * R + 3, "little")
    del prod

    mask = (1 << 20) - 1
    ans = 0

    if g == 1:
        for x in S:
            b = x - minS
            o = 5 * b
            c = (pb[o] | (pb[o + 1] << 8) | (pb[o + 2] << 16)) & mask
            ans += (c - 1) >> 1
    else:
        for x in S:
            b = (x - minS) // g
            o = 5 * b
            c = (pb[o] | (pb[o + 1] << 8) | (pb[o + 2] << 16)) & mask
            ans += (c - 1) >> 1

    return ans


def count_numpy(S, minS, g, R, N, np):
    arr = np.array(S, dtype=np.int64)
    if g == 1:
        idx = arr - minS
    else:
        idx = (arr - minS) // g
    del arr

    n = 1 << (2 * R).bit_length()
    f = np.zeros(n, dtype=np.float64)
    f[idx] = 1.0

    F = np.fft.rfft(f)
    del f
    F *= F
    conv = np.fft.irfft(F, n=n)
    del F

    c = np.rint(conv[2 * idx]).astype(np.int64)
    return int(((c - 1) // 2).sum())


def main():
    data = sys.stdin.buffer.read().split()
