import sys

MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    size = 1 << N
    s_vals = [ord(ch) - ord('a') for ch in S]

    # A DP row for LCS(S[:i], current_string) is nondecreasing
    # and increases by only 0 or 1, so it can be encoded by a bitmask.
    trans = []
    for mask in range(size):
        f = [0] * (N + 1)
        for i in range(1, N + 1):
            f[i] = f[i - 1] + ((mask >> (i - 1)) & 1)

        cnt = {}
        for c in range(26):
            g = [0] * (N + 1)
            for i in range(1, N + 1):
                best = f[i]
                if g[i - 1] > best:
                    best = g[i - 1]
                if s_vals[i - 1] == c:
                    v = f[i - 1] + 1
                    if v > best:
                        best = v
                g[i] = best

            nm = 0
            prev = 0
            for i in range(1, N + 1):
                if g[i] != prev:
                    nm |= 1 << (i - 1)
                prev = g[i]

            cnt[nm] = cnt.get(nm, 0) + 1

        trans.append(list(cnt.items()))

    dp = [0] * size
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * size
        for mask, val in enumerate(dp):
            if val:
                for nm, c in trans[mask]:
                    ndp[nm] += val * c
        for i in range(size):
            ndp[i] %= MOD
        dp = ndp

    pop = [0] * size
    for i in range(1, size):
        pop[i] = pop[i >> 1] + (i & 1)

    ans = [0] * (N + 1)
    for mask, val in enumerate(dp):
        if val:
            ans[pop[mask]] = (ans[pop[mask]] + val) % MOD

    print(" ".join(map(str, ans)))

