import sys
from collections import deque
import heapq

def main():
    input = sys.stdin.readline
    N, M, S, T = map(int, input().split())
    S -= 1
    T -= 1
    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        dist = [-1] * N
        dist[start] = 0
        q = deque([start])
        order = []
        while q:
            v = q.popleft()
            order.append(v)
            for to in adj[v]:
                if dist[to] == -1:
                    dist[to] = dist[v] + 1
                    q.append(to)
        return dist, order

    distS, orderS = bfs(S)
    distT, _ = bfs(T)
    D = distS[T]

    on_path = [distS[i] + distT[i] == D for i in range(N)]

    # Count shortest paths, capped at 2.
    cnt = [0] * N
    cnt[S] = 1
    for v in orderS:
        if not on_path[v] or cnt[v] == 0:
            continue
        cv = cnt[v]
        for to in adj[v]:
            if on_path[to] and distS[to] == distS[v] + 1:
                nv = cnt[to] + cv
                cnt[to] = 2 if nv >= 2 else nv

    # If there are at least two distinct shortest paths, they can be scheduled
    # without any extra move.
    if cnt[T] >= 2:
        print(2 * D)
        return

    INF = 10**18
    min_extra = INF

    # Internal vertex on the unique shortest path with an off-path edge:
    # one token can make a 2-move spike.
    for v in range(N):
        if on_path[v] and v != S and v != T:
            for to in adj[v]:
                if not on_path[to]:
                    if 2 < min_extra:
                        min_extra = 2
                    break

    # Endpoint "room" cost.
    vis = [0] * N
    token = 0

    def endpoint_cost(p):
        nonlocal token
        off = []
        for to in adj[p]:
            if not on_path[to]:
                off.append(to)
        if len(off) >= 2:
            return 4
        if len(off) == 1:
            token += 1
            start = off[0]
            q = deque([(start, 1)])
            vis[start] = token
            while q:
                v, d = q.popleft()
                deg = 0
                for to in adj[v]:
                    if not on_path[to] and to != p:
                        deg += 1
                        if vis[to] != token:
                            vis[to] = token
                            q.append((to, d + 1))
                if deg >= 2:
                    return 4 * d + 4
            return INF
        return INF

    min_extra = min(min_extra, endpoint_cost(S), endpoint_cost(T))

    # If the best possible extra is already 1, no need for the Dijkstra part.
    if min_extra > 1:
        # Multi-source Dijkstra on G - shortest_path.
        # Source p (on the path) starts at an adjacent off-path vertex c
        # with initial value pos[p] = distS[p].
        # For a boundary vertex p and entry c, if the best source is a != p,
        # candidate extra = 2 + (dist(c_a, c) + pos[a]) - pos[p].
        val1 = [INF] * N
        src1 = [-1] * N
        val2 = [INF] * N
        src2 = [-1] * N
        heap = []

        def add_label(v, val, src):
            if src == src1[v]:
                if val < val1[v]:
                    val1[v] = val
                    heapq.heappush(heap, (val, v, src))
                return
            if src == src2[v]:
                if val < val2[v]:
                    val2[v] = val
                    heapq.heappush(heap, (val, v, src))
                return
            if val < val1[v]:
                val2[v] = val1[v]
                src2[v] = src1[v]
                val1[v] = val
                src1[v] = src
                heapq.heappush(heap, (val, v, src))
            elif val < val2[v]:
                val2[v] = val
                src2[v] = src
                heapq.heappush(heap, (val, v, src))

        for p in range(N):
            if on_path[p]:
                base = distS[p]
                for c in adj[p]:
                    if not on_path[c]:
                        add_label(c, base, p)

        while heap:
            val, v, src = heapq.heappop(heap)
            ok = False
            if src == src1[v] and val == val1[v]:
                ok = True
            elif src == src2[v] and val == val2[v]:
                ok = True
            if not ok:
                continue
            nv = val + 1
            for to in adj[v]:
                if not on_path[to]:
                    add_label(to, nv, src)

        for p in range(N):
            if not on_path[p]:
                continue
            base = distS[p]
            for c in adj[p]:
                if on_path[c]:
                    continue
                best = INF
                if src1[c] != -1 and src1[c] != p:
                    best = val1[c]
                elif src2[c] != -1 and src2[c] != p:
                    best = val2[c]
                if best != INF:
                    cand = 2 + best - base
                    if cand < 0:
                        cand = 0
                    if cand < min_extra:
                        min_extra = cand

    if min_extra == INF:
        print(-1)
    else:
        print(2 * D + min_extra)

