import sys
from bisect import bisect_left


def build_f(items, cap):
    if cap <= 0:
        return [0]
    if not items:
        return [0] * (cap + 1)

    buckets = [[] for _ in range(cap + 1)]
    for c, a in items:
        if c <= cap:
            buckets[c].append(a)

    dp = [0] * (cap + 1)
    cur = 0

    for c in range(1, cap + 1):
        lst = buckets[c]
        if not lst:
            continue

        limit = cap // c
        lst.sort(reverse=True)
        if len(lst) > limit:
            del lst[limit:]

        for a in lst:
            new_cur = cur + c
            if new_cur > cap:
                new_cur = cap

            if new_cur > cur:
                val = dp[cur]
                if val:
                    for i in range(cur + 1, new_cur + 1):
                        dp[i] = val

            for w in range(new_cur, c - 1, -1):
                nv = dp[w - c] + a
                if nv > dp[w]:
                    dp[w] = nv

            cur = new_cur

    if cur < cap:
        val = dp[cur]
        if val:
            for i in range(cur + 1, cap + 1):
                dp[i] = val

    best = 0
    for i in range(1, cap + 1):
        if dp[i] < best:
            dp[i] = best
        else:
            best = dp[i]

    return dp


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, X = data[0], data[1]
    groups = [[], [], []]
    totals = [0, 0, 0]
    min_cost = [X + 1, X + 1, X + 1]
    total_cal = 0

    idx = 2
    for _ in range(N):
        v, a, c = data[idx], data[idx + 1], data[idx + 2]
        idx += 3
        gi = v - 1
        groups[gi].append((c, a))
        totals[gi] += a
        if c < min_cost[gi]:
            min_cost[gi] = c
        total_cal += c

    min_total = min(totals)

    if total_cal <= X:
        print(min_total)
        return

    min_cost_sum = min_cost[0] + min_cost[1] + min_cost[2]
    if min_total == 0 or min_cost_sum > X:
        print(0)
        return

    if min_total == 1:
        print(1)
        return

    caps = [0, 0, 0]
    for i in range(3):
        caps[i] = X - min_cost[(i + 1) % 3] - min_cost[(i + 2) % 3]

    fns = [build_f(groups[i], caps[i]) for i in range(3)]
    max_possible = min(f[-1] for f in fns)

    if max_possible == 0:
        print(0)
        return

    lo, hi = 0, max_possible + 1
    lens = [len(f) for f in fns]

    while hi - lo > 1:
        mid = (lo + hi) // 2
        cost = 0
        ok = True

        for i in range(3):
            pos = bisect_left(fns[i], mid)
            if pos == lens[i]:
                ok = False
                break
            cost += pos
            if cost > X:
                ok = False
                break

        if ok:
            lo = mid
        else:
            hi = mid

    print(lo)


