import sys
import gc


def solve():
    gc.disable()
    data = sys.stdin.buffer.readline().split()
    if not data:
        return
    N = int(data[0])
    mod = int(data[1])

    n = N // 2
    D = N * (N - 1) // 2
    maxD = max(D, N)

    inv = [0] * (maxD + 2)
    inv[1] = 1
    for i in range(2, maxD + 2):
        inv[i] = mod - (mod // i) * inv[mod % i] % mod

    fact = [1] * (maxD + 2)
    for i in range(1, maxD + 2):
        fact[i] = fact[i - 1] * i % mod

    # max_len[t] = C(t, 2) + 1
    max_len = [0] * (N + 1)
    for t in range(N + 1):
        max_len[t] = t * (t - 1) // 2 + 1

    S = n + 1
    S2 = S * S
    size = S * S * S

    def shift_diff(H, b, a, cap, inv_mul, mod=mod):
        """Return H * y^b * (y^a - 1) * inv_mul, truncated to length cap."""
        if len(H) == 1 and H[0] == 0:
            return [0]

        L = len(H)
        s1 = b + a
        s2 = b
        new_len = L + s1
        if new_len > cap:
            new_len = cap
        new = [0] * new_len

        # Range where only the -y^b term is present.
        start = s2
        end = s1
        tmp = L + s2
        if end > tmp:
            end = tmp
        if end > new_len:
            end = new_len
        if start < end:
            j = 0
            if inv_mul == 1:
                for m in range(start, end):
                    v = H[j]
                    j += 1
                    if v:
                        new[m] = mod - v
            else:
                inv = inv_mul
                for m in range(start, end):
                    v = H[j]
                    j += 1
                    if v:
                        new[m] = (mod - v) * inv % mod

        # Range where both terms are present.
        start = s1
        end = L + s2
        if end > new_len:
            end = new_len
        if start < end:
            jx = 0
            jy = a  # s1 - s2
            if inv_mul == 1:
                for m in range(start, end):
                    v = H[jx] - H[jy]
                    jx += 1
                    jy += 1
                    if v < 0:
                        v += mod
                    new[m] = v
            else:
                inv = inv_mul
                for m in range(start, end):
                    v = H[jx] - H[jy]
                    jx += 1
                    jy += 1
                    if v < 0:
                        v += mod
                    if v:
                        new[m] = v * inv % mod

        # Range where only the +y^(b+a) term is present.
        start = L + s2
        if start < s1:
            start = s1
        end = L + s1
        if end > new_len:
            end = new_len
        if start < end:
            jx = start - s1
            if inv_mul == 1:
                for m in range(start, end):
                    new[m] = H[jx]
                    jx += 1
            else:
                inv = inv_mul
                for m in range(start, end):
                    v = H[jx]
                    jx += 1
                    if v:
                        new[m] = v * inv % mod

        if len(new) > 1 and new[-1] == 0:
            while len(new) > 1 and new[-1] == 0:
                new.pop()
        return new

    def add_poly(dst, src, mod=mod):
        if len(src) == 1 and src[0] == 0:
            return
        ld = len(dst)
        ls = len(src)
        if ls > ld:
            dst.extend([0] * (ls - ld))
        for i in range(ls):
            v = dst[i] + src[i]
            if v >= mod:
                v -= mod
            dst[i] = v
        if len(dst) > 1 and dst[-1] == 0:
            while len(dst) > 1 and dst[-1] == 0:
                dst.pop()

    # State: (even_used, odd_used, current_layer_size)
    # Flat index: (e * S + o) * S + a
    dp = [None] * size
    dp[1 * S2 + 0 * S + 1] = [1]  # root: even=1, odd=0, layer size 1

    final_poly = None

    shift = shift_diff
    add = add_poly
    inv_list = inv
    mlen = max_len

    for layer_idx in range(N):
        next_dp = [None] * size
        has_next = False
        p = layer_idx & 1

        if p == 0:
            # Current layer is even, next layer is odd.
            for e in range(1, S):
                base_e = e * S2
                max_a = e
                for o in range(S):
                    base = base_e + o * S

                    if e == n and o == n:
                        for a in range(1, max_a + 1):
                            F = dp[base + a]
                            if F is None:
                                continue
                            if len(F) == 1 and F[0] == 0:
                                continue
                            if final_poly is None:
                                final_poly = F.copy()
                            else:
                                add(final_poly, F)
                        continue

                    max_b = n - o
                    if max_b <= 0:
                        continue

                    t = e + o
                    cap1 = mlen[t + 1]
                    next_base_e = base_e

                    for a in range(1, max_a + 1):
                        F = dp[base + a]
                        if F is None:
                            continue
                        if len(F) == 1 and F[0] == 0:
                            continue

                        H = shift(F, 0, a, cap1, 1)
                        for b in range(1, max_b + 1):
                            if len(H) == 1 and H[0] == 0:
                                break

                            idx = next_base_e + (o + b) * S + b
                            target = next_dp[idx]
                            if target is None:
                                next_dp[idx] = H
                                has_next = True
                            else:
                                add(target, H)
                                has_next = True

                            if b < max_b:
                                H = shift(H, b, a, mlen[t + b + 1], inv_list[b + 1])
        else:
            # Current layer is odd, next layer is even.
            for o in range(1, S):
                max_a = o
                o_base = o * S
                for e in range(1, S):
                    base = e * S2 + o_base

                    if e == n and o == n:
                        for a in range(1, max_a + 1):
                            F = dp[base + a]
                            if F is None:
                                continue
                            if len(F) == 1 and F[0] == 0:
                                continue
                            if final_poly is None:
                                final_poly = F.copy()
                            else:
                                add(final_poly, F)
                        continue

                    max_b = n - e
                    if max_b <= 0:
                        continue

                    t = e + o
                    cap1 = mlen[t + 1]

                    for a in range(1, max_a + 1):
                        F = dp[base + a]
                        if F is None:
                            continue
                        if len(F) == 1 and F[0] == 0:
                            continue

                        H = shift(F, 0, a, cap1, 1)
                        for b in range(1, max_b + 1):
                            if len(H) == 1 and H[0] == 0:
                                break

                            idx = (e + b) * S2 + o_base + b
                            target = next_dp[idx]
                            if target is None:
                                next_dp[idx] = H
                                has_next = True
                            else:
                                add(target, H)
                                has_next = True

                            if b < max_b:
                                H = shift(H, b, a, mlen[t + b + 1], inv_list[b + 1])

        dp = next_dp
        if not has_next:
            break

    if final_poly is None:
        final_poly = [0]
    if len(final_poly) < D + 1:
        final_poly.extend([0] * (D + 1 - len(final_poly)))

    factN1 = fact[N - 1]
    ans = [0] * (D + 1)

    # Convert from y-polynomial to x-polynomial:
    # H_x(x) = H_y(1 + x)
    for k in range(D + 1):
        ck = final_poly[k]
        if ck == 0:
            continue
        ck = ck * factN1 % mod
        comb = 1
        for m in range(k + 1):
            add_val = ck * comb % mod
            v = ans[m] + add_val
            if v >= mod:
                v -= mod
            ans[m] = v
            if m < k:
                comb = comb * (k - m) % mod * inv[m + 1] % mod

    sys.stdout.write(" ".join(str(ans[m]) for m in range(N - 1, D + 1)) + "\n")


