    solve()

import sys
from math import isqrt
from bisect import bisect_right


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    P = [p for p in data[2:2 + N] if p <= M]

    if not P:
        print(0)
        return

    P.sort()
    p_min = P[0]
    maxP_all = P[-1]

    # Upper bound 1: use only the cheapest product.
    t_min = isqrt(M // p_min)
    hi = p_min * (2 * t_min + 1)

    # Upper bound 2: buy the same number of units from every product.
    sumP = sum(P)
    x = isqrt(M // sumP) + 1
    hi2 = maxP_all * (2 * x - 1)
    if hi2 < hi:
        hi = hi2

    # Products whose first marginal cost is above hi can never be used.
    if maxP_all > hi:
        P = P[:bisect_right(P, hi)]

    maxP = P[-1]
    MM = M

    def over(c, P=P, maxP=maxP, MM=MM):
        total = 0
        if c >= maxP:
            for p in P:
                t = (c // p + 1) >> 1
                total += p * t * t
                if total > MM:
                    return True
        else:
            for p in P:
                if p > c:
                    break
                t = (c // p + 1) >> 1
                total += p * t * t
                if total > MM:
                    return True
        return False

    lo = 0
    while hi - lo > 1:
        mid = (lo + hi) >> 1
        if over(mid):
            hi = mid
        else:
            lo = mid

    C = hi
    c = C - 1

    cost = 0
    units = 0

    if c >= maxP:
        for p in P:
            t = (c // p + 1) >> 1
            cost += p * t * t
            units += t
    else:
        for p in P:
            if p > c:
                break
            t = (c // p + 1) >> 1
            cost += p * t * t
            units += t

    ans = units + (M - cost) // C
    print(ans)


