import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M = data[0], data[1]
    A = [x - 1 for x in data[2:2 + N]]
    del data

    indeg = [0] * N
    for a in A:
        indeg[a] += 1

    q = deque([i for i, d in enumerate(indeg) if d == 0])
    removed = [False] * N
    order = []
    while q:
        u = q.popleft()
        removed[u] = True
        order.append(u)
        v = A[u]
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)

    is_cycle = [not removed[i] for i in range(N)]

    children = [[] for _ in range(N)]
    for i in range(N):
        if not is_cycle[i]:
            children[A[i]].append(i)

    size = [1] * N
    for u in order:
        size[A[u]] += size[u]

    for u in range(N):
        if len(children[u]) > 1:
            children[u].sort(key=size.__getitem__, reverse=True)

    del indeg, removed, order, size

    mod = MOD
    sys.setrecursionlimit(1000000)
    M1 = M + 1
    rng = range(1, M1)
    leaf_template = list(range(M1))
    leaf_copy = leaf_template.copy

    def compute(u, is_root, children=children, rng=rng, M1=M1, mod=mod, leaf_copy=leaf_copy):
        F = None
        for c in children[u]:
            S = compute(c, False)
            if F is None:
                F = S
            else:
                for p in rng:
                    F[p] = (F[p] * S[p]) % mod
            del S

        if F is None:
            if is_root:
                return None
            return leaf_copy()

        if is_root:
            return F

        S = [0] * M1
        run = 0
        for p in rng:
            run += F[p]
            if run >= mod:
                run -= mod
            S[p] = run
        del F
        return S

    visited = [False] * N
    ans = 1

    for i in range(N):
        if is_cycle[i] and not visited[i]:
            cur = i
            cycle_nodes = []
            while not visited[cur]:
                visited[cur] = True
                cycle_nodes.append(cur)
                cur = A[cur]

            prod = None
            for node in cycle_nodes:
                if children[node]:
                    F = compute(node, True)
                    if prod is None:
                        prod = F
                    else:
                        for p in rng:
                            prod[p] = (prod[p] * F[p]) % mod
                    del F

            if prod is None:
                comp = M % mod
            else:
                comp = 0
                for p in rng:
                    comp += prod[p]
                    if comp >= mod:
                        comp -= mod
                del prod

            ans = (ans * comp) % mod

    print(ans)

if __name__ == "__main__":
    main()

