import sys


def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    K = int(data[0])
    S = data[1]
    T = data[2]

    n = len(S)
    m = len(T)

    if abs(n - m) > K:
        sys.stdout.write("No\n")
        return

    # Edit distance is symmetric.  Make S the shorter string.
    if n > m:
        S, T = T, S
        n, m = m, n

    # If K is at least the longer length, we can always do it:
    # replace up to n characters and insert the remaining m-n characters.
    if K >= m:
        sys.stdout.write("Yes\n")
        return

    # LCP of S[i:] and T[j:] using block comparisons.
    B = 1 << 16

    def lcp(i, j, n=n, m=m, T=T, startswith=S.startswith, B=B):
        max_len = n - i
        rem = m - j
        if rem < max_len:
            max_len = rem
        if max_len <= 0:
            return 0

        pos = 0
        while pos + B <= max_len:
            if startswith(T[j + pos:j + pos + B], i + pos):
                pos += B
            else:
                break

        lo = pos
        hi = pos + B
        if hi > max_len:
            hi = max_len

        while lo < hi:
            mid = (lo + hi + 1) >> 1
            if startswith(T[j + lo:j + mid], i + lo):
                lo = mid
            else:
                hi = mid - 1

        return lo

    # Landau-Vishkin algorithm.
    # d = i - j, where i is consumed length of S, j of T.
    off = K
    size = 2 * K + 1
    final_idx = off + (n - m)

    prev = [-1] * size
    prev[off] = lcp(0, 0)

    if prev[final_idx] >= n:
        sys.stdout.write("Yes\n")
        return

    for e in range(1, K + 1):
        curr = [-1] * size

        for idx in range(off - e, off + e + 1):
            d = idx - off
            carry = prev[idx]
            best = carry

            # Substitution: same diagonal, consume one character from both.
            if carry >= 0:
                pj = carry - d
                if carry < n and 0 <= pj < m:
                    cand = carry + 1
                    if cand > best:
                        best = cand

            # Deletion from S: previous diagonal d-1, consume one from S.
            if idx > 0:
                pi = prev[idx - 1]
                if pi >= 0 and pi < n:
                    pj = pi - d + 1
                    if 0 <= pj <= m:
                        cand = pi + 1
                        if cand > best:
                            best = cand

            # Insertion into S: previous diagonal d+1, consume one from T.
            if idx + 1 < size:
                pi = prev[idx + 1]
                if pi >= 0:
                    pj = pi - d - 1
                    if 0 <= pj < m:
                        cand = pi
                        if cand > best:
                            best = cand

            if best >= 0:
                if best > carry:
                    curr[idx] = best + lcp(best, best - d)
                else:
                    curr[idx] = best

        if curr[final_idx] >= n:
            sys.stdout.write("Yes\n")
            return

        prev = curr

    sys.stdout.write("No\n")


if __name__ == "__main__":
    solve()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # Current longest run of identical characters.
        max_run = 1
        cur = 1
        for i in range(1, n):
            if s[i] == s[i - 1]:
                cur += 1
            else:
                cur = 1
            if cur > max_run:
                max_run = cur

        if max_run == 1 or numOps == 0:
            return max_run

        # Any binary string can be made alternating with at most floor(n / 2) flips.
        if numOps >= n // 2:
            return 1

        bits = [1 if ch == '1' else 0 for ch in s]

        def can(limit: int) -> bool:
            INF = numOps + 1

            # dp0[l] = min flips for processed prefix ending with '0',
            #          current run length exactly l.
            # dp1[l] = same for ending with '1'.
            first = bits[0]
            cost0 = first
            cost1 = 1 - first

            dp0 = [INF, cost0 if cost0 <= numOps else INF]
            dp1 = [INF, cost1 if cost1 <= numOps else INF]
            min0 = dp0[1]
            min1 = dp1[1]

            for i in range(1, n):
                new_limit = limit if limit < i + 1 else i + 1

                ndp0 = [INF] * (new_limit + 1)
                ndp1 = [INF] * (new_limit + 1)

                cost0 = bits[i]
                cost1 = 1 - cost0

                new_min0 = INF
                v = min1 + cost0
                if v < INF:
                    ndp0[1] = v
                    new_min0 = v

                for length in range(2, new_limit + 1):
                    v = dp0[length - 1] + cost0
                    if v < INF:
                        ndp0[length] = v
                        if v < new_min0:
                            new_min0 = v

                new_min1 = INF
                v = min0 + cost1
                if v < INF:
                    ndp1[1] = v
                    new_min1 = v

                for length in range(2, new_limit + 1):
                    v = dp1[length - 1] + cost1
                    if v < INF:
                        ndp1[length] = v
                        if v < new_min1:
                            new_min1 = v

                dp0, dp1 = ndp0, ndp1
                min0, min1 = new_min0, new_min1

                if min0 == INF and min1 == INF:
                    return False

            return min0 <= numOps or min1 <= numOps

        lo, hi = 1, max_run
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

