import sys

SHIFT = 18
CMASK = (1 << SHIFT) - 1
LIST_THRESHOLD = 1 << 21


def calc_dict(d, target, mask):
    total = 0
    get = d.get
    shift = SHIFT
    cmask = CMASK

    for r, val in d.items():
        b = (target - r) & mask
        if b == r:
            c = val & cmask
            s = val >> shift
            total += (c + 1) * s
        elif r < b:
            val2 = get(b)
            if val2:
                c = val & cmask
                s = val >> shift
                c2 = val2 & cmask
                s2 = val2 >> shift
                total += s * c2 + s2 * c
    return total


def calc_list(arr, touched, target, mask):
    total = 0
    shift = SHIFT
    cmask = CMASK

    for r in touched:
        val = arr[r]
        b = (target - r) & mask
        if b == r:
            c = val & cmask
            s = val >> shift
            total += (c + 1) * s
        elif r < b:
            val2 = arr[b]
            if val2:
                c = val & cmask
                s = val >> shift
                c2 = val2 & cmask
                s2 = val2 >> shift
                total += s * c2 + s2 * c
    return total


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N]
    del data
    N = len(A)

    shift = SHIFT
    pairs = []
    pairs_append = pairs.append
    base = {}
    bget = base.get
    maxA = 0

    for a in A:
        if a > maxA:
            maxA = a
        incv = (a << shift) + 1
        pairs_append((a, incv))
        old = bget(a)
        if old is None:
            base[a] = incv
        else:
            base[a] = old + incv

    del A, bget, pairs_append

    U = len(base)
    use_base_build = (U * 2 <= N)
    if use_base_build:
        base_items = list(base.items())
        del pairs
    else:
        base_items = None

    max_sum = maxA << 1
    ans = 0
    threshold = LIST_THRESHOLD

    for t in range(max_sum.bit_length()):
        target = 1 << t
        M = target << 1
        mask = M - 1

        if M > maxA:
            total = calc_dict(base, target, mask)

        elif M <= threshold:
            arr = [0] * M
            touched = []
            append = touched.append

            if use_base_build:
                for v, val in base_items:
                    r = v & mask
                    cur = arr[r]
                    if cur == 0:
                        append(r)
                        arr[r] = val
                    else:
                        arr[r] = cur + val
            else:
                for a, incv in pairs:
                    r = a & mask
                    cur = arr[r]
                    if cur == 0:
                        append(r)
                        arr[r] = incv
                    else:
                        arr[r] = cur + incv

            total = calc_list(arr, touched, target, mask)
            del arr, touched, append

        else:
            d = {}
            dget = d.get

            if use_base_build:
                for v, val in base_items:
                    r = v & mask
                    old = dget(r)
                    if old is None:
                        d[r] = val
                    else:
                        d[r] = old + val
            else:
                for a, incv in pairs:
                    r = a & mask
                    old = dget(r)
                    if old is None:
                        d[r] = incv
                    else:
                        d[r] = old + incv

            total = calc_dict(d, target, mask)
            del d, dget

        ans += (total >> t)

    print(ans)


if __name__ == "__main__":
    main()

import sys
from bisect import bisect_left

def get_sequence(inv, balls, x, total, n):
    if total == 0 or balls[x] == total:
        return []
    order = []
    append = order.append
    cur = x
    cycle_balls = 0
    maxd = 0
    found = False
    for d in range(n):
        append(cur)
        b = balls[cur]
        if b:
            cycle_balls += b
            if d > maxd:
                maxd = d
        cur = inv[cur]
        if cur == x:
            found = True
            break
    if not found or cycle_balls != total:
        return None
    return order[maxd:0:-1]

def lcs_length(a, b, n):
    if not a or not b:
        return 0
    if len(a) > len(b):
        a, b = b, a
    pos = [-1] * n
    for i, v in enumerate(b):
        pos[v] = i
    tails = []
    bl = bisect_left
    for v in a:
        p = pos[v]
        if p != -1:
            i = bl(tails, p)
            if i == len(tails):
                tails.append(p)
            else:
                tails[i] = p
    return len(tails)

def main():
    it = map(int, sys.stdin.buffer.read().split())
