    X = next(it) - 1

    A = [0] * N
    totalA = 0
    for i in range(N):
        v = next(it)
        A[i] = v
        totalA += v

    B = [0] * N
    totalB = 0
    for i in range(N):
        v = next(it)
        B[i] = v
        totalB += v

    needP = totalA > 0 and A[X] < totalA
    needQ = totalB > 0 and B[X] < totalB

    if not needP and not needQ:
        print(0)
        return

    invP = None
    if needP:
        invP = [0] * N
        for i in range(N):
            invP[next(it) - 1] = i
        red_seq = get_sequence(invP, A, X, totalA, N)
        if red_seq is None:
            print(-1)
            return
    else:
        for _ in range(N):
            next(it)
        red_seq = []

    del A, invP

    invQ = None
    if needQ:
        invQ = [0] * N
        for i in range(N):
            invQ[next(it) - 1] = i
        blue_seq = get_sequence(invQ, B, X, totalB, N)
        if blue_seq is None:
