from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold
        small = [x for x in nums if x <= T]
        if not small:
            return len(nums)
        if len(small) == 1:
            return 1 + len(nums) - len(small)

        small.sort()
        limit = T + 1
        parent = list(range(limit))
        size = [1] * limit

        def find(a, parent=parent):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a

        covered = bytearray(limit)
        p = parent
        sz = size
        cov = covered
        find_root = find

        for x in small:
            if cov[x]:
                continue
            rx = find_root(x)
            for m in range(x * 2, limit, x):
                rb = find_root(m)
                if rx != rb:
                    if sz[rx] < sz[rb]:
                        p[rx] = rb
                        sz[rb] += sz[rx]
                        rx = rb
                    else:
                        p[rb] = rx
                        sz[rx] += sz[rb]
                cov[m] = 1

        roots = set()
        for x in small:
            roots.add(find_root(x))

        return len(roots) + (len(nums) - len(small))
